int
shapes_ping_call(cbl_conn *c, const struct shapes_ping_input *in,
    struct shapes_ping_output *out, cbl_yarena *a, int timeout_ms)
{
	cbl_msg *m, *r;
	int error;

	if ((error = cbl_msg_new(cbl_conn_ctx(c), CBL_YANG_FAMILY,
	    CBL_YCMD_RPC, 0, &m)) != 0)
		return (error);
	if ((error = cbl_msg_put_ynode(m, &n32, in)) != 0) {
		cbl_msg_free(m);
		return (error);
	}
	if ((error = cbl_request(c, m, &r, timeout_ms)) == 0)
		error = cbl_msg_ydecode(r, &n34, out, a, CBL_YD_STRICT, NULL,
		    0);
	cbl_msg_free(r);
	return (error);
}

